/**
 * useTabVideoRecorder
 *
 * Hook that drives a tab-capture video recording from the sidepanel UI.
 * Talks to the SW via VIDEO_REQUEST and listens for VIDEO_EVENT broadcasts
 * coming back from the offscreen recorder. Uploads the resulting blob to
 * cld_files and appends a row to the recordings store so the user sees the
 * recording in their list.
 *
 * Lifecycle states:
 *   - idle           — nothing active
 *   - permission     — checking / requesting tabCapture
 *   - starting       — VIDEO_REQUEST sent, waiting for `started`
 *   - recording      — `started` received, capturing
 *   - stopping       — user stopped or duration elapsed; awaiting `complete`
 *   - uploading      — bytes received, posting to cld_files
 *   - error          — terminal; the consumer can reset by calling reset()
 */

import { uploadFile } from '@/lib/api/routes/files';
import { log } from '@/lib/debug/log';
import { base64ToBlob } from '@/lib/messaging/binary-transport';
import { CHANNELS } from '@/lib/messaging/schemas';
import { hasOptionalPermissions, requestOptionalPermission } from '@/lib/permissions/optional';
import { type RecordingEntry, useRecordingsStore } from '@/lib/video/recordings-store';
import type { VideoEvent, VideoRequestPayload } from '@/lib/video/video-types';
import { useCallback, useEffect, useRef, useState } from 'react';

export type RecorderStatus =
  | 'idle'
  | 'permission'
  | 'starting'
  | 'recording'
  | 'stopping'
  | 'uploading'
  | 'error';

export interface UseTabVideoRecorderResult {
  status: RecorderStatus;
  errorMessage: string | null;
  /** ms since `started`. Updates roughly every 200ms while recording. */
  elapsedMs: number;
  /** Wall-clock duration of the most recent finished recording. */
  lastDurationMs: number | null;
  /** Active session id; null when idle. */
  sessionId: string | null;
  /**
   * Whether the consumer should render the recovery dialog. Opens ONLY
   * after Chrome rejects a real `chrome.permissions.request` call —
   * never as pre-attempt UI.
   */
  recoveryDialogOpen: boolean;
  /** Begin the recording flow. */
  start: (opts: { tabId: number; durationMs: number; audio: boolean }) => Promise<void>;
  stop: () => Promise<void>;
  reset: () => void;
  /** Called when the user clicks "Open extension permissions". */
  confirmRecoveryDialog: () => Promise<void>;
  /** Called when the user dismisses the recovery dialog. */
  closeRecoveryDialog: () => void;
}

function newSessionId(): string {
  return `vid-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
}

function sanitizeFilename(input: string): string {
  return (
    input
      .replace(/[\\/:*?"<>|]/g, '-')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 100) || 'recording'
  );
}

function extensionFor(mimeType: string): string {
  if (mimeType.startsWith('video/webm')) return 'webm';
  if (mimeType.startsWith('video/mp4')) return 'mp4';
  return 'webm';
}

export function useTabVideoRecorder(): UseTabVideoRecorderResult {
  const [status, setStatus] = useState<RecorderStatus>('idle');
  // Busy-state watchdog: 'starting' / 'stopping' / 'uploading' with a lost
  // event used to brick the recorder until remount — no Stop, no reset, just
  // a frozen badge. The deadline flips to a recoverable error instead.
  const busyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const statusRef = useRef<RecorderStatus>('idle');
  statusRef.current = status;
  const armBusyWatchdog = useCallback((stage: 'starting' | 'stopping' | 'uploading') => {
    if (busyTimerRef.current) clearTimeout(busyTimerRef.current);
    const deadline = stage === 'uploading' ? 120_000 : 30_000;
    busyTimerRef.current = setTimeout(() => {
      if (statusRef.current !== stage) return; // moved on — all good
      setStatus('error');
      setErrorMessage(
        `Recorder stuck on "${stage}" — no response from the capture pipeline. Dismiss and try again.`,
      );
    }, deadline);
  }, []);
  useEffect(
    () => () => {
      if (busyTimerRef.current) clearTimeout(busyTimerRef.current);
    },
    [],
  );
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [elapsedMs, setElapsedMs] = useState(0);
  const [lastDurationMs, setLastDurationMs] = useState<number | null>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [recoveryDialogOpen, setRecoveryDialogOpen] = useState(false);

  const sessionIdRef = useRef<string | null>(null);
  const startTimeRef = useRef<number>(0);
  const tickRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const tabSnapshotRef = useRef<{ title: string | null; url: string | null }>({
    title: null,
    url: null,
  });
  const audioRef = useRef<boolean>(false);
  const addRecording = useRecordingsStore((s) => s.add);

  const stopTick = useCallback(() => {
    if (tickRef.current) {
      clearInterval(tickRef.current);
      tickRef.current = null;
    }
  }, []);

  const reset = useCallback(() => {
    stopTick();
    setStatus('idle');
    setErrorMessage(null);
    setElapsedMs(0);
    setSessionId(null);
    sessionIdRef.current = null;
  }, [stopTick]);

  const handleComplete = useCallback(
    async (data: string, mimeType: string, durationMs: number, source: 'tab' | 'display') => {
      setStatus('uploading');
      armBusyWatchdog('uploading');
      setLastDurationMs(durationMs);
      const ext = extensionFor(mimeType);
      const titleBase = tabSnapshotRef.current.title
        ? sanitizeFilename(tabSnapshotRef.current.title)
        : 'tab';
      const filename = `${titleBase}-${Date.now()}.${ext}`;

      // `data` is a base64 string (chrome.runtime.sendMessage uses JSON,
      // not structured clone). Decode back to a Blob before upload.
      // See @/lib/messaging/binary-transport.
      const blob = base64ToBlob(data, mimeType);
      log.info('sys', 'video: complete received', {
        base64Length: data.length,
        decodedBytes: blob.size,
        durationMs,
        source,
      });

      try {
        const upload = await uploadFile(blob, filename, {
          path: `browser-agent/recordings/${filename}`,
          metadata: {
            source: source === 'tab' ? 'tab_capture' : 'display_capture',
            duration_ms: durationMs,
            audio: audioRef.current,
          },
        });
        const entry: RecordingEntry = {
          id: sessionIdRef.current ?? newSessionId(),
          capturedAt: new Date().toISOString(),
          tabTitle: tabSnapshotRef.current.title,
          tabUrl: tabSnapshotRef.current.url,
          fileId: upload.file_id,
          fileUrl: upload.url ?? upload.cdn_url ?? null,
          durationMs,
          sizeBytes: blob.size,
          mimeType,
          audio: audioRef.current,
          source,
        };
        await addRecording(entry);
        reset();
      } catch (err) {
        log.error('sys', 'recording upload failed', err);
        setStatus('error');
        setErrorMessage(`Upload failed: ${(err as Error).message}`);
      }
    },
    [addRecording, reset],
  );

  // Subscribe once to VIDEO_EVENT broadcasts. We filter by sessionIdRef so
  // recordings started in other surfaces don't trigger our state machine.
  useEffect(() => {
    const listener = (msg: unknown): boolean | undefined => {
      if (
        !msg ||
        typeof msg !== 'object' ||
        (msg as { __matrx?: unknown }).__matrx !== true ||
        (msg as { kind?: unknown }).kind !== CHANNELS.VIDEO_EVENT
      ) {
        return false;
      }
      const event = (msg as { payload?: VideoEvent }).payload;
      if (!event) return false;
      const expected = sessionIdRef.current;
      if (!expected || event.sessionId !== expected) return false;

      switch (event.type) {
        case 'started': {
          startTimeRef.current = Date.now();
          setElapsedMs(0);
          setStatus('recording');
          stopTick();
          tickRef.current = setInterval(() => {
            setElapsedMs(Date.now() - startTimeRef.current);
          }, 200);
          break;
        }
        case 'stopped': {
          setStatus('stopping');
          armBusyWatchdog('stopping');
          stopTick();
          break;
        }
        case 'complete': {
          stopTick();
          void handleComplete(event.data, event.mimeType, event.durationMs, event.source);
          break;
        }
        case 'error': {
          stopTick();
          setStatus('error');
          setErrorMessage(event.message);
          break;
        }
      }
      return false;
    };
    chrome.runtime.onMessage.addListener(listener);
    return () => {
      chrome.runtime.onMessage.removeListener(listener);
      stopTick();
    };
  }, [handleComplete, stopTick]);

  const launchRecording = useCallback(
    async (opts: { tabId: number; durationMs: number; audio: boolean }) => {
      // Snapshot the tab so we can label the recording entry once it lands.
      try {
        const tab = await chrome.tabs.get(opts.tabId);
        tabSnapshotRef.current = {
          title: tab?.title ?? null,
          url: tab?.url ?? null,
        };
      } catch {
        tabSnapshotRef.current = { title: null, url: null };
      }

      audioRef.current = opts.audio;
      const id = newSessionId();
      sessionIdRef.current = id;
      setSessionId(id);
      setStatus('starting');
      armBusyWatchdog('starting');
      setElapsedMs(0);
      setLastDurationMs(null);

      const payload: VideoRequestPayload = {
        sessionId: id,
        action: 'start',
        targetTabId: opts.tabId,
        audio: opts.audio,
        durationMs: opts.durationMs,
        source: 'tab',
      };
      try {
        const res = (await chrome.runtime.sendMessage({
          __matrx: true,
          kind: CHANNELS.VIDEO_REQUEST,
          payload,
        })) as { ok?: boolean; __error?: string } | undefined;
        if (res && '__error' in res && res.__error) {
          setStatus('error');
          setErrorMessage(res.__error);
        } else if (!res || res.ok === false) {
          // undefined = no listener answered (SW asleep / handler missing);
          // ok:false = refused. Both used to leave the badge on "Starting"
          // forever with Record disabled and no escape hatch.
          setStatus('error');
          setErrorMessage('Recorder did not start — the service worker did not respond.');
        }
      } catch (err) {
        setStatus('error');
        setErrorMessage(`Failed to start recording: ${(err as Error).message}`);
      }
    },
    [],
  );

  const start = useCallback(
    async (opts: { tabId: number; durationMs: number; audio: boolean }) => {
      // Always attempt the live permission request immediately. Chrome's
      // own native dialog is the only "asking" UI the user should see;
      // we never compete with it via a pre-attempt explainer modal.
      // If Chrome already has the permission, the request resolves true
      // silently. If not, Chrome shows its native prompt — and only on
      // rejection do we open our recovery dialog (with one-click access
      // to the extension's permission page).
      setErrorMessage(null);
      setStatus('permission');
      const granted = await hasOptionalPermissions(['tabCapture']);
      if (granted) {
        await launchRecording(opts);
        return;
      }
      const ok = await requestOptionalPermission('tabCapture');
      if (!ok) {
        setStatus('idle');
        setRecoveryDialogOpen(true);
        return;
      }
      await launchRecording(opts);
    },
    [launchRecording],
  );

  const confirmRecoveryDialog = useCallback(async () => {
    // Open the extension's own permission page in a new tab. We navigate
    // FOR the user — no "type chrome://..." instructions.
    try {
      await chrome.tabs.create({
        url: `chrome://extensions/?id=${chrome.runtime.id}`,
      });
    } catch (err) {
      log.warn('sys', 'open extension permissions failed', err);
    }
    setRecoveryDialogOpen(false);
  }, []);

  const closeRecoveryDialog = useCallback(() => {
    setRecoveryDialogOpen(false);
  }, []);

  const stop = useCallback(async () => {
    const id = sessionIdRef.current;
    if (!id) return;
    setStatus('stopping');
    const payload: VideoRequestPayload = { sessionId: id, action: 'stop' };
    try {
      await chrome.runtime.sendMessage({
        __matrx: true,
        kind: CHANNELS.VIDEO_REQUEST,
        payload,
      });
    } catch (err) {
      log.warn('sys', 'video stop forward failed', err);
    }
  }, []);

  return {
    status,
    errorMessage,
    elapsedMs,
    lastDurationMs,
    sessionId,
    recoveryDialogOpen,
    start,
    stop,
    reset,
    confirmRecoveryDialog,
    closeRecoveryDialog,
  };
}
